/**
 * apply-realm-translations.mjs — seed hand-authored realm/stage/chapter
 * translations from scripts/i18n-realms.json into all 9 locale game.json files.
 *
 * Run:  node scripts/apply-realm-translations.mjs
 *
 * Idempotent. Re-run after a `pull --drafts` if Polyglyph overwrites these
 * hand-authored values with AI drafts. EN is untouched (its values are auto-
 * generated by scripts/gen_game_i18n.mjs from src/data/realms.js).
 */
import fs from 'node:fs';
import path from 'node:path';

const LOCALES_DIR = path.resolve('src/i18n/locales');
const manifest = JSON.parse(fs.readFileSync(path.resolve('scripts/i18n-realms.json'), 'utf8'));

const LANGS = ['zh', 'ja', 'ko', 'pt', 'es', 'fr', 'de', 'it', 'ru'];

const sortDeep = (o) => (o && typeof o === 'object' && !Array.isArray(o))
  ? Object.fromEntries(Object.keys(o).sort().map(k => [k, sortDeep(o[k])]))
  : o;

let touched = 0;
for (const lang of LANGS) {
  const file = path.join(LOCALES_DIR, lang, 'game.json');
  if (!fs.existsSync(file)) { console.warn(`  ${lang}: game.json not found, skipping`); continue; }
  const game = JSON.parse(fs.readFileSync(file, 'utf8'));

  // realmNames: { "<en>": { "name": "<tr>" } }
  game.realmNames = {};
  for (const [en, byLang] of Object.entries(manifest.realmNames)) {
    if (byLang[lang]) game.realmNames[en] = { name: byLang[lang] };
  }
  // realmStages: { "<en>": { "label": "<tr>" } }
  game.realmStages = {};
  for (const [en, byLang] of Object.entries(manifest.realmStages)) {
    if (byLang[lang]) game.realmStages[en] = { label: byLang[lang] };
  }
  // chapters: { "<id>": { "title": "<tr>" } }
  game.chapters = {};
  for (const [id, byLang] of Object.entries(manifest.chapters)) {
    if (byLang[lang]) game.chapters[id] = { title: byLang[lang] };
  }

  const sorted = sortDeep(game);
  fs.writeFileSync(file, JSON.stringify(sorted, null, 2) + '\n', 'utf8');
  const counts = `${Object.keys(game.realmNames).length} realmNames, ${Object.keys(game.realmStages).length} realmStages, ${Object.keys(game.chapters).length} chapters`;
  console.log(`  ${lang}: ${counts}`);
  touched += 1;
}
console.log(`\nDone. ${touched} locale files updated.`);
